
.row {
  display: flex;
  align-items: flex-start;
  gap: 9px;
  padding: 3px 0;
}

.label {
  flex: 0 0 auto;
  width: 3.4em;
  font-size: 10.5px;
  letter-spacing: 1px;
  color: var(--c-text-muted);
  padding-top: 1px;
}

.value {
  flex: 1 1 auto;
  min-width: 0;
}

.part {
  font-size: 12px;
  line-height: 1.65;
  overflow-wrap: anywhere;
  color: var(--c-text);
}

.part.is-body {
  color: var(--c-body);
}

.part.is-kai {
  font-family: var(--font-accent);
  font-size: 12.5px;
  color: var(--c-primary);
}
