
.board {
  padding: 9px 12px 10px;
  display: flex;
  flex-direction: column;
}

.head {
  display: flex;
  align-items: baseline;
  flex-wrap: wrap;
  gap: 8px;
  padding-bottom: 6px;
  margin-bottom: 5px;
  border-bottom: 1px solid var(--c-border);
}

.who {
  flex: 1 1 auto;
  min-width: 0;
  font-size: 14px;
  font-weight: 600;
  letter-spacing: 1px;
  color: var(--c-primary);
  overflow-wrap: anywhere;
}

.who em {
  font-style: normal;
  font-weight: 400;
  font-size: 11px;
  letter-spacing: 0;
  color: var(--c-text-muted);
}

.tags {
  flex: 0 0 auto;
  display: inline-flex;
  gap: 4px;
}

.tags i {
  font-style: normal;
  font-size: 10px;
  letter-spacing: 0.5px;
  color: var(--c-primary);
  border: 1px solid var(--c-primary-soft);
  border-radius: 2px;
  padding: 0 5px;
}

.shop {
  margin-top: 7px;
  padding-top: 6px;
  border-top: 1px dashed var(--c-border);
  font-size: 10.5px;
  color: var(--c-text-muted);
}
